import{XO_CONFIG as p}from"./config.min.js";import{createPlay as l,lineUp as f,OFFENSIVE_PLAYS as b}from"./play.min.js";import{resolvePlay as m}from"./design.min.js";export const DEFAULT_SLOT="qb";const s=(e,t,n,r)=>Object.freeze({id:e,team:t,label:n,phrase:r}),a=(e,t,n,r)=>Array.from({length:t},(S,o)=>s(`${e}${o+1}`,n,`${r} ${o+1}`,`${r.toLowerCase()} ${o+1}`));export const SLOTS=Object.freeze([s("qb",0,"Quarterback","quarterback"),...["wr1","wr2","wr3","wr4"].map(e=>{const t=p.receivers[e].letter;return s(e,0,`Receiver ${t}`,`receiver ${t}`)}),...a("x",6,0,"Lineman"),...a("db",4,1,"Defensive back"),...a("s",2,1,"Safety")]);const u=new Map(SLOTS.map(e=>[e.id,e]));export function isSlot(e){return typeof e=="string"&&u.has(e)}export function normalizeSlot(e){return isSlot(e)?e:DEFAULT_SLOT}export function slotOf(e){return u.get(normalizeSlot(e))}export function labelOf(e){return slotOf(e).label}const x=new Set(["x4","x5","x6"]);export function listedSlots(e=DEFAULT_SLOT){const t=normalizeSlot(e);return SLOTS.filter(n=>!x.has(n.id)||n.id===t)}export function playingLine(e){const t=slotOf(e);return t.id===DEFAULT_SLOT?"You take the snap at quarterback as your avatar.":`You line up at ${t.phrase} as your avatar.`}let c=null;const i=new Map;export function benchedIn(e){const t=m(e).base;if(!b.includes(t))return new Set;if(!i.has(t)){c||(c=l());const n=f(c,t,"cover2");i.set(t,new Set(n.filter(r=>r.settings.team===0&&r.settings.benched).map(r=>r.settings.position)))}return new Set(i.get(t))}export function sitsOut(e,t){return benchedIn(t).has(normalizeSlot(e))}
